                                    ExcelFont.NormalWeight, false, false);
                var bgTextFormat = ExcelFormat(childIndex % 2 == 0 ? Color.FromArgb(248, 248, 248) : Color.FromArgb(217, 232, 235), HorizontalAlignmentStyle.Center,
                                     ExcelFont.NormalWeight, false, false);
