                        MarginTotalBookings15minsOu = NumberFormat.DecFormat(Grand_m_TotalBookings15minOu * 100, 2),
                        MarginCorners15minsOU = NumberFormat.DecFormat(Grand_m_Corners15minOu * 100, 2),
                        Margin10minsOu = NumberFormat.DecFormat(Grand_m_10minOu * 100, 2),
                        MarginSingleTeamOu = NumberFormat.DecFormat(Grand_m_SingleTeamOu * 100, 2),

                        UserName = string.Empty,
                        League = string.Empty,
                        Match = string.Empty
                    };

                    #endregion assign footer

                    result.footer = traderFooter;

                    #endregion footer
                }
            }
            catch
            {
            }
            finally
            {
                #region assign session

                switch (isSoccer)
                {
                    case 1:
                        SessionExtension.AddSession(HttpContext.Current.Session, TraderPerformanceDetailIsSoccerSessionKey, result);
                        break;

                    case 0:
                        SessionExtension.AddSession(HttpContext.Current.Session, TraderPerformanceDetailIsNoSoccerSessionKey, result);
                        break;

                    default:
                        break;
                }

                #endregion assign session
            }
            return result;

            #endregion get new data
        }

        #endregion get traderperformance report detail
    }
}